using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Reflection;using System.Threading;using System.Windows.Forms;using System.Windows.Automation;using System.Web.Script.Serialization;
class UiaProbe {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;static int checks;static string root;static Form app;static List<object> trace=new List<object>();static Assembly assembly;
 static void Check(bool b,string message){Console.WriteLine((b?"PASS ":"FAIL ")+message);checks++;if(!b)throw new Exception(message);}
 static object Call(object o,string name,params object[] args){Type t=o as Type??o.GetType();return t.GetMethods(F).First(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(o is Type?null:o,args);}
 static IEnumerable<Control> Walk(Control c){yield return c;foreach(Control v in c.Controls)foreach(var n in Walk(v))yield return n;}
 static void Pump(){Application.DoEvents();Thread.Sleep(2);}
 static void Client(Action action){Exception failure=null;var thread=new Thread(()=>{try{action();}catch(Exception ex){failure=ex;}}){IsBackground=true};thread.SetApartmentState(ApartmentState.MTA);thread.Start();var deadline=DateTime.UtcNow.AddSeconds(45);while(thread.IsAlive&&DateTime.UtcNow<deadline)Pump();Check(!thread.IsAlive,"Native UI Automation client returns without blocking the STA");if(failure!=null)throw failure;}
 [STAThread]static int Main(string[] args){root=args[1];Directory.CreateDirectory(root);try{Application.EnableVisualStyles();assembly=Assembly.LoadFile(Path.GetFullPath(args[0]));Call(assembly.GetType("Frociart.UiMotion"),"SetEnabled",false);Call(assembly.GetType("Frociart.Ui"),"SetDarkMode",false,false);app=(Form)Activator.CreateInstance(assembly.GetType("Frociart.MainForm"),F,null,new object[]{null,true},null);app.ShowInTaskbar=false;app.StartPosition=FormStartPosition.Manual;app.Location=Point.Empty;app.Size=new Size(1420,900);app.Show();Call(app,"EnterEditor");object diagram=Call(assembly.GetType("Frociart.Examples"),"Parity");Call(app,"SetDocument",diagram,null,false);for(int i=0;i<250;i++)Pump();Call(app,"EnterEditor");for(int i=0;i<50;i++)Pump();Check(((Control)app.GetType().GetField("Canvas",F).GetValue(app)).Visible,"Editor canvas is visible after deferred startup settles");
  var known=Walk(app).Where(c=>c.Name.StartsWith("Task",StringComparison.Ordinal)||c.Name=="QuickCommands"||c.Name=="QuickSave").Select(c=>new{handle=c.Handle,id=c.Name,name=c.AccessibleName??c.Text,enabled=c.Enabled}).ToArray();
  Client(()=>{var top=AutomationElement.FromHandle(app.Handle);Check(top.Current.ControlType==ControlType.Window,"UIA exposes the actual native top-level window");var rows=new List<object>();foreach(var entry in known){var item=AutomationElement.FromHandle(entry.handle);var current=item.Current;Check(current.ControlType==ControlType.Button,"UIA exposes button role: "+entry.id);Check(current.Name==entry.name,"UIA exposes its actual accessible name: "+entry.id);Check(current.IsEnabled==entry.enabled,"UIA exposes the actual enabled state: "+entry.id);rows.Add(new{id=entry.id,name=current.Name,type=current.ControlType.ProgrammaticName,enabled=current.IsEnabled,focusable=current.IsKeyboardFocusable});}trace.Add(new{phase="direct-native-control-providers",elements=rows});});

  app.Activate();var order=new List<object>();for(int i=0;i<60;i++){bool moved=app.SelectNextControl(app.ActiveControl,true,true,true,true);for(int j=0;j<5;j++)Pump();Control current=app.ActiveControl;while(current is ContainerControl&&((ContainerControl)current).ActiveControl!=null)current=((ContainerControl)current).ActiveControl;order.Add(new{step=i,moved=moved,name=current==null?null:current.AccessibleName??current.Text,id=current==null?null:current.Name,type=current==null?null:current.GetType().FullName,providerName=current==null?null:current.AccessibilityObject.Name,providerRole=current==null?null:current.AccessibilityObject.Role.ToString(),enabled=current!=null&&current.Enabled,tabStop=current!=null&&current.TabStop});Check(current!=null&&current.Enabled,"Tab traversal reaches an enabled native control at step "+i);}trace.Add(new{phase="native-focus-traversal",order=order});
  Check(!order.Any(row=>(string)row.GetType().GetProperty("type").GetValue(row,null)=="Frociart.BrandMark"),"Decorative brand artwork is absent from the keyboard Tab cycle");
  var caption=Walk(app).OfType<TextBox>().First(t=>t.Visible&&t.Text=="Pari o dispari");caption.Focus();for(int i=0;i<20;i++)Pump();Client(()=>{var element=AutomationElement.FromHandle(caption.Handle);object pattern;Check(element.TryGetCurrentPattern(ValuePattern.Pattern,out pattern),"UIA exposes native editor value pattern");var value=(ValuePattern)pattern;Check(value.Current.Value=="Pari o dispari","UIA reads the actual current project title");Check(!value.Current.IsReadOnly,"UIA reports that the title is editable");trace.Add(new{phase="title-value-pattern",name=element.Current.Name,value=value.Current.Value,readOnly=value.Current.IsReadOnly,hasKeyboardFocus=element.Current.HasKeyboardFocus});});
  using(var image=new Bitmap(app.Width,app.Height)){app.DrawToBitmap(image,new Rectangle(Point.Empty,app.Size));image.Save(Path.Combine(root,"uia-editor.png"));}Call(app,"SetDocument",Call(assembly.GetType("Frociart.DiagramIO"),"CreateBlank"),null,false);app.Close();File.WriteAllText(Path.Combine(root,"uia.json"),new JavaScriptSerializer{MaxJsonLength=4*1024*1024}.Serialize(new{status="PASS_UIA_NOT_SCREENREADER",checks=checks,trace=trace,scope="Real Windows UIAutomation client on a private native desktop; no Narrator audio or user desktop/settings were used"}));Console.WriteLine("UIA_PROBE PASS checks="+checks);return 0;
 }catch(Exception ex){Console.WriteLine(ex);File.WriteAllText(Path.Combine(root,"failure.txt"),ex.ToString());File.WriteAllText(Path.Combine(root,"failure-trace.json"),new JavaScriptSerializer{MaxJsonLength=4*1024*1024}.Serialize(trace));return 1;}finally{if(app!=null&&!app.IsDisposed)app.Dispose();}}
}
